#!/usr/bin/env bash
set -euo pipefail
rm -rf .backend migrations app /tmp/healthcare-backend-bundle.tgz
cat > /tmp/healthcare-backend-bundle.tgz.b64 <<'B64EOF'

B64EOF
base64 -d /tmp/healthcare-backend-bundle.tgz.b64 > /tmp/healthcare-backend-bundle.tgz
tar -xzf /tmp/healthcare-backend-bundle.tgz

ROOT="$(pwd)"
if [ -d "$ROOT/backend" ]; then
  rm -rf "$ROOT/.backend"
  mv "$ROOT/backend" "$ROOT/.backend"
elif [ ! -d "$ROOT/.backend" ]; then
  echo "ERROR: backend source was not extracted"
  find "$ROOT" -maxdepth 2 -type f | head -50
  exit 1
fi

if [ ! -f "$ROOT/.backend/go.mod" ]; then
  echo "ERROR: go.mod missing at $ROOT/.backend/go.mod"
  find "$ROOT/.backend" -maxdepth 2 -type f | head -80
  exit 1
fi

echo "Backend source: $ROOT/.backend"
ls -la "$ROOT/.backend/go.mod"
cd "$ROOT/.backend"
echo "Go module: $(go env GOMOD)"
go mod download
gofmt -w ./internal ./cmd
cd "$ROOT"
go build -o app "$ROOT/.backend/cmd/server"
ls -lh "$ROOT/app"
